// Checkout access bridge: connect the checkout buttons to the existing auth dialogs.
(() => {
  const byId = (id) => document.getElementById(id);
  const openLogin = byId("btnOpenLogin");
  const openRegister = byId("btnOpenRegister");
  const gateLogin = byId("btnGateLogin");
  const gateRegister = byId("btnGateRegister");
  const gate = byId("checkoutAuthGate");
  const payment = byId("paymentForm");
  const badge = byId("sessionBadge");

  gateLogin?.addEventListener("click", () => openLogin?.click());
  gateRegister?.addEventListener("click", () => openRegister?.click());

  const syncCheckoutAccess = () => {
    const loggedIn = Boolean(badge && !badge.classList.contains("hidden"));
    gate?.classList.toggle("hidden", loggedIn);
    payment?.classList.toggle("hidden", !loggedIn);
  };

  if (badge) {
    new MutationObserver(syncCheckoutAccess).observe(badge, {
      attributes: true,
      attributeFilter: ["class"]
    });
  }
  syncCheckoutAccess();
})();
